const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});
    const t = target.result;
    const is_darwin = t.os.tag.isDarwin();
    const is_windows = t.os.tag == .windows;

    const tls = b.option(Tls, "tls", "Enable tls support using the specified library") orelse .disabled;
    const networking = b.option(bool, "networking", "Enable networking") orelse true;

    if (!networking and tls != .disabled) {
        std.debug.panic("TLS requires networking", .{});
    }

    const libz_dep = b.dependency("libz", .{
        .target = target,
        .optimize = optimize,
    });
    const lazy_mbedtls_dep = if (tls == .mbedtls) b.lazyDependency("mbedtls", .{
        .target = target,
        .optimize = optimize,
    }) else null;
    const lazy_openssl_dep = if (tls == .openssl) b.lazyDependency("openssl", .{
        .target = target,
        .optimize = optimize,
    }) else null;
    // const lazy_libressl_dep = if (tls == .libressl) b.lazyDependency("libressl", .{
    //     .target = target,
    //     .optimize = optimize,
    // }) else null;
    const libmp3lame_dep = b.dependency("libmp3lame", .{
        .target = target,
        .optimize = optimize,
    });
    const libvorbis_dep = b.dependency("libvorbis", .{
        .target = target,
        .optimize = optimize,
    });
    const libogg_dep = b.dependency("libogg", .{
        .target = target,
        .optimize = optimize,
    });

    const omit_frame_pointer = false;
    const pic = true;
    const lib = b.addLibrary(.{ .name = "ffmpeg", .root_module = b.createModule(.{
        .target = target,
        .optimize = optimize,
        .link_libc = true,
        .omit_frame_pointer = omit_frame_pointer,
        .pic = pic,
    }) });
    lib.root_module.linkLibrary(libz_dep.artifact("z"));
    if (lazy_mbedtls_dep) |mbedtls_dep| lib.root_module.linkLibrary(mbedtls_dep.artifact("mbedtls"));
    if (lazy_openssl_dep) |openssl_dep| lib.root_module.linkLibrary(openssl_dep.artifact("openssl"));
    // if (lazy_libressl_dep) |libressl_dep| lib.root_module.linkLibrary(libressl_dep.artifact("ssl"));
    lib.root_module.linkLibrary(libmp3lame_dep.artifact("mp3lame"));
    lib.root_module.linkLibrary(libvorbis_dep.artifact("vorbis"));
    lib.root_module.linkLibrary(libogg_dep.artifact("ogg"));
    lib.root_module.addIncludePath(b.path("."));
    if (is_windows) {
        // Upstream configure's mingw EXTRALIBS.
        lib.root_module.linkSystemLibrary("ws2_32", .{});
        lib.root_module.linkSystemLibrary("bcrypt", .{});
    }

    const avconfig_h = b.addConfigHeader(.{
        .style = .blank,
        .include_path = "libavutil/avconfig.h",
    }, .{
        .AV_HAVE_BIGENDIAN = t.cpu.arch.endian() == .big,
        .AV_HAVE_FAST_UNALIGNED = fastUnalignedLoads(t),
    });
    lib.root_module.addConfigHeader(avconfig_h);

    const common_config = .{
        .ARCH_AARCH64 = t.cpu.arch.isAARCH64(),
        .ARCH_ARM = t.cpu.arch.isArm(),
        .ARCH_IA64 = false,
        .ARCH_LOONGARCH = switch (t.cpu.arch) {
            .loongarch32, .loongarch64 => true,
            else => false,
        },
        .ARCH_LOONGARCH32 = t.cpu.arch == .loongarch32,
        .ARCH_LOONGARCH64 = t.cpu.arch == .loongarch64,
        .ARCH_M68K = t.cpu.arch == .m68k,
        .ARCH_MIPS = switch (t.cpu.arch) {
            .mips, .mipsel => true,
            else => false,
        },
        .ARCH_MIPS64 = switch (t.cpu.arch) {
            .mips64, .mips64el => true,
            else => false,
        },
        .ARCH_PARISC = false,
        .ARCH_PPC = t.cpu.arch.isPowerPC(),
        .ARCH_PPC64 = t.cpu.arch.isPowerPC64(),
        .ARCH_RISCV = t.cpu.arch.isRISCV(),
        .ARCH_S390 = t.cpu.arch == .s390x,
        .ARCH_SPARC = t.cpu.arch.isSPARC(),
        .ARCH_SPARC64 = t.cpu.arch == .sparc64,
        .ARCH_TILEGX = false,
        .ARCH_TILEPRO = false,
        .ARCH_WASM = t.cpu.arch.isWasm(),
        .ARCH_X86 = t.cpu.arch.isX86(),
        .ARCH_X86_32 = have_x86_feat(t, .@"32bit_mode"),
        .ARCH_X86_64 = have_x86_feat(t, .@"64bit"),

        .HAVE_ARMV5TE = have_arm_feat(t, .has_v5te),
        .HAVE_ARMV6 = have_arm_feat(t, .has_v6),
        .HAVE_ARMV6T2 = have_arm_feat(t, .has_v6t2),
        .HAVE_ARMV8 = have_arm_feat(t, .has_v8) or have_aarch64_feat(t, .v8a),
        .HAVE_ARM_CRC = have_arm_feat(t, .crc) or have_aarch64_feat(t, .crc),
        .HAVE_DOTPROD = have_arm_feat(t, .dotprod) or have_aarch64_feat(t, .dotprod),
        .HAVE_I8MM = have_arm_feat(t, .i8mm) or have_aarch64_feat(t, .i8mm),
        .HAVE_NEON = have_arm_feat(t, .neon) or have_aarch64_feat(t, .neon),
        .HAVE_VFP = have_arm_feat(t, .vfp2),
        .HAVE_VFPV3 = have_arm_feat(t, .vfp3),
        .HAVE_SETEND = false,
        .HAVE_SVE = have_aarch64_feat(t, .sve),
        .HAVE_SVE2 = have_aarch64_feat(t, .sve2),
        .HAVE_SME = have_aarch64_feat(t, .sme),
        .HAVE_SME_I16I64 = have_aarch64_feat(t, .sme_i16i64),
        .HAVE_SME2 = have_aarch64_feat(t, .sme2),
        .HAVE_ALTIVEC = have_ppc_feat(t, .altivec),
        .HAVE_DCBZL = false,
        .HAVE_LDBRX = have_ppc_feat(t, .ldbrx),
        .HAVE_POWER8 = have_ppc_feat(t, .power8_vector),
        .HAVE_PPC4XX = have_ppc_feat(t, .ppc4xx),
        .HAVE_VEC_XL = false,
        .HAVE_VSX = have_ppc_feat(t, .vsx),
        .HAVE_RV = false,
        .HAVE_RVV = false,
        .HAVE_RV_ZICBOP = false,
        .HAVE_RV_ZVBB = false,
        .HAVE_SIMD128 = have_wasm_feat(t, .simd128),
        .HAVE_AESNI = have_x86_feat(t, .aes),
        .HAVE_CLMUL = false,
        .HAVE_AMD3DNOW = have_x86_feat(t, .@"3dnow"),
        .HAVE_AMD3DNOWEXT = have_x86_feat(t, .@"3dnow"),
        .HAVE_AVX = have_x86_feat(t, .avx),
        .HAVE_AVX2 = have_x86_feat(t, .avx2),
        .HAVE_AVX512 = have_x86_feat(t, .avx512f),
        .HAVE_AVX512ICL = have_x86_feat(t, .avx512f),
        .HAVE_FMA3 = have_x86_feat(t, .fma),
        .HAVE_FMA4 = have_x86_feat(t, .fma4),
        .HAVE_MMX = have_x86_feat(t, .mmx),
        .HAVE_MMXEXT = have_x86_feat(t, .mmx),
        .HAVE_SSE = have_x86_feat(t, .sse),
        .HAVE_SSE2 = have_x86_feat(t, .sse2),
        .HAVE_SSE3 = have_x86_feat(t, .sse3),
        .HAVE_SSE4 = have_x86_feat(t, .sse4_1),
        .HAVE_SSE42 = have_x86_feat(t, .sse4_2),
        .HAVE_SSSE3 = have_x86_feat(t, .ssse3),
        .HAVE_XOP = have_x86_feat(t, .xop),
        .HAVE_I686 = have_x86_feat(t, .cmov) and
            have_x86_feat(t, .cx8) and
            have_x86_feat(t, .vzeroupper) and
            have_x86_feat(t, .x87),
        .HAVE_MIPSFPU = missing_mips_feat(t, .soft_float),
        .HAVE_MIPS32R2 = have_mips_feat(t, .mips32r2),
        .HAVE_MIPS32R5 = have_mips_feat(t, .mips32r5),
        .HAVE_MIPS64R2 = have_mips_feat(t, .mips64r2),
        .HAVE_MIPS32R6 = have_mips_feat(t, .mips32r6),
        .HAVE_MIPS64R6 = have_mips_feat(t, .mips64r6),
        .HAVE_MIPSDSP = have_mips_feat(t, .dsp),
        .HAVE_MIPSDSPR2 = have_mips_feat(t, .dspr2),
        .HAVE_MSA = have_mips_feat(t, .msa),
        .HAVE_LOONGSON2 = false,
        .HAVE_LOONGSON3 = false,
        .HAVE_MMI = false,
        .HAVE_LSX = false,
        .HAVE_LASX = false,

        .HAVE_ARMV5TE_EXTERNAL = have_arm_feat(t, .has_v5te),
        .HAVE_ARMV6_EXTERNAL = have_arm_feat(t, .has_v6),
        .HAVE_ARMV6T2_EXTERNAL = have_arm_feat(t, .has_v6t2),
        .HAVE_ARMV8_EXTERNAL = have_arm_feat(t, .has_v8) or have_aarch64_feat(t, .v8a),
        .HAVE_ARM_CRC_EXTERNAL = have_arm_feat(t, .crc) or have_aarch64_feat(t, .crc),
        .HAVE_DOTPROD_EXTERNAL = have_arm_feat(t, .dotprod) or have_aarch64_feat(t, .dotprod),
        .HAVE_I8MM_EXTERNAL = have_arm_feat(t, .i8mm) or have_aarch64_feat(t, .i8mm),
        .HAVE_NEON_EXTERNAL = have_arm_feat(t, .neon) or have_aarch64_feat(t, .neon),
        .HAVE_VFP_EXTERNAL = have_arm_feat(t, .vfp2),
        .HAVE_VFPV3_EXTERNAL = have_arm_feat(t, .vfp3),
        .HAVE_SETEND_EXTERNAL = false,
        .HAVE_SVE_EXTERNAL = have_aarch64_feat(t, .sve),
        .HAVE_SVE2_EXTERNAL = have_aarch64_feat(t, .sve2),
        .HAVE_SME_EXTERNAL = have_aarch64_feat(t, .sme),
        .HAVE_SME_I16I64_EXTERNAL = have_aarch64_feat(t, .sme_i16i64),
        .HAVE_SME2_EXTERNAL = have_aarch64_feat(t, .sme2),
        .HAVE_ALTIVEC_EXTERNAL = have_ppc_feat(t, .altivec),
        .HAVE_DCBZL_EXTERNAL = false,
        .HAVE_LDBRX_EXTERNAL = have_ppc_feat(t, .ldbrx),
        .HAVE_POWER8_EXTERNAL = have_ppc_feat(t, .power8_vector),
        .HAVE_PPC4XX_EXTERNAL = have_ppc_feat(t, .ppc4xx),
        .HAVE_VEC_XL_EXTERNAL = false,
        .HAVE_VSX_EXTERNAL = have_ppc_feat(t, .vsx),
        .HAVE_RV_EXTERNAL = false,
        .HAVE_RVV_EXTERNAL = false,
        .HAVE_RV_ZICBOP_EXTERNAL = false,
        .HAVE_RV_ZVBB_EXTERNAL = false,
        .HAVE_SIMD128_EXTERNAL = have_wasm_feat(t, .simd128),
        .HAVE_AESNI_EXTERNAL = have_x86_feat(t, .aes),
        .HAVE_CLMUL_EXTERNAL = false,
        .HAVE_AMD3DNOW_EXTERNAL = have_x86_feat(t, .@"3dnow"),
        .HAVE_AMD3DNOWEXT_EXTERNAL = have_x86_feat(t, .@"3dnowa"),
        .HAVE_AVX_EXTERNAL = have_x86_feat(t, .avx),
        .HAVE_AVX2_EXTERNAL = have_x86_feat(t, .avx2),
        .HAVE_AVX512_EXTERNAL = have_x86_feat(t, .avx512f),
        .HAVE_AVX512ICL_EXTERNAL = have_x86_feat(t, .avx512f),
        .HAVE_FMA3_EXTERNAL = have_x86_feat(t, .fma),
        .HAVE_FMA4_EXTERNAL = have_x86_feat(t, .fma4),
        .HAVE_MMX_EXTERNAL = have_x86_feat(t, .mmx),
        .HAVE_MMXEXT_EXTERNAL = have_x86_feat(t, .mmx),
        .HAVE_SSE_EXTERNAL = have_x86_feat(t, .sse),
        .HAVE_SSE2_EXTERNAL = have_x86_feat(t, .sse2),
        .HAVE_SSE3_EXTERNAL = have_x86_feat(t, .sse3),
        .HAVE_SSE4_EXTERNAL = have_x86_feat(t, .sse4_1),
        .HAVE_SSE42_EXTERNAL = have_x86_feat(t, .sse4_2),
        .HAVE_SSSE3_EXTERNAL = have_x86_feat(t, .ssse3),
        .HAVE_XOP_EXTERNAL = have_x86_feat(t, .xop),
        .HAVE_I686_EXTERNAL = have_x86_feat(t, .cmov) and
            have_x86_feat(t, .cx8) and
            have_x86_feat(t, .vzeroupper) and
            have_x86_feat(t, .x87),
        .HAVE_MIPSFPU_EXTERNAL = missing_mips_feat(t, .soft_float),
        .HAVE_MIPS32R2_EXTERNAL = have_mips_feat(t, .mips32r2),
        .HAVE_MIPS32R5_EXTERNAL = have_mips_feat(t, .mips32r5),
        .HAVE_MIPS64R2_EXTERNAL = have_mips_feat(t, .mips64r2),
        .HAVE_MIPS32R6_EXTERNAL = have_mips_feat(t, .mips32r6),
        .HAVE_MIPS64R6_EXTERNAL = have_mips_feat(t, .mips64r6),
        .HAVE_MIPSDSP_EXTERNAL = have_mips_feat(t, .dsp),
        .HAVE_MIPSDSPR2_EXTERNAL = have_mips_feat(t, .dspr2),
        .HAVE_MSA_EXTERNAL = have_mips_feat(t, .msa),
        .HAVE_LOONGSON2_EXTERNAL = false,
        .HAVE_LOONGSON3_EXTERNAL = false,
        .HAVE_MMI_EXTERNAL = false,
        .HAVE_LSX_EXTERNAL = false,
        .HAVE_LASX_EXTERNAL = false,

        .HAVE_ARMV5TE_INLINE = have_arm_feat(t, .has_v5te),
        .HAVE_ARMV6_INLINE = have_arm_feat(t, .has_v6),
        .HAVE_ARMV6T2_INLINE = have_arm_feat(t, .has_v6t2),
        .HAVE_ARMV8_INLINE = have_arm_feat(t, .has_v8) or have_aarch64_feat(t, .v8a),
        .HAVE_ARM_CRC_INLINE = have_arm_feat(t, .crc) or have_aarch64_feat(t, .crc),
        .HAVE_DOTPROD_INLINE = have_arm_feat(t, .dotprod) or have_aarch64_feat(t, .dotprod),
        .HAVE_I8MM_INLINE = have_arm_feat(t, .i8mm) or have_aarch64_feat(t, .i8mm),
        .HAVE_NEON_INLINE = have_arm_feat(t, .neon) or have_aarch64_feat(t, .neon),
        .HAVE_VFP_INLINE = have_arm_feat(t, .vfp2),
        .HAVE_VFPV3_INLINE = have_arm_feat(t, .vfp3),
        .HAVE_SETEND_INLINE = false,
        .HAVE_SVE_INLINE = have_aarch64_feat(t, .sve),
        .HAVE_SVE2_INLINE = have_aarch64_feat(t, .sve2),
        .HAVE_SME_INLINE = have_aarch64_feat(t, .sme),
        .HAVE_SME_I16I64_INLINE = have_aarch64_feat(t, .sme_i16i64),
        .HAVE_SME2_INLINE = have_aarch64_feat(t, .sme2),
        .HAVE_ALTIVEC_INLINE = have_ppc_feat(t, .altivec),
        .HAVE_DCBZL_INLINE = false,
        .HAVE_LDBRX_INLINE = have_ppc_feat(t, .ldbrx),
        .HAVE_POWER8_INLINE = have_ppc_feat(t, .power8_vector),
        .HAVE_PPC4XX_INLINE = have_ppc_feat(t, .ppc4xx),
        .HAVE_VEC_XL_INLINE = false,
        .HAVE_VSX_INLINE = have_ppc_feat(t, .vsx),
        .HAVE_RV_INLINE = false,
        .HAVE_RVV_INLINE = false,
        .HAVE_RV_ZICBOP_INLINE = false,
        .HAVE_RV_ZVBB_INLINE = false,
        .HAVE_SIMD128_INLINE = have_wasm_feat(t, .simd128),
        .HAVE_AESNI_INLINE = have_x86_feat(t, .aes),
        .HAVE_CLMUL_INLINE = false,
        .HAVE_AMD3DNOW_INLINE = have_x86_feat(t, .@"3dnow"),
        .HAVE_AMD3DNOWEXT_INLINE = have_x86_feat(t, .@"3dnowa"),
        .HAVE_AVX_INLINE = have_x86_feat(t, .avx),
        .HAVE_AVX2_INLINE = have_x86_feat(t, .avx2),
        .HAVE_AVX512_INLINE = have_x86_feat(t, .avx512f),
        .HAVE_AVX512ICL_INLINE = have_x86_feat(t, .avx512f),
        .HAVE_FMA3_INLINE = have_x86_feat(t, .fma),
        .HAVE_FMA4_INLINE = have_x86_feat(t, .fma4),
        .HAVE_MMX_INLINE = have_x86_feat(t, .mmx),
        .HAVE_MMXEXT_INLINE = have_x86_feat(t, .mmx),
        .HAVE_SSE_INLINE = have_x86_feat(t, .sse),
        .HAVE_SSE2_INLINE = have_x86_feat(t, .sse2),
        .HAVE_SSE3_INLINE = have_x86_feat(t, .sse3),
        .HAVE_SSE4_INLINE = have_x86_feat(t, .sse4_1),
        .HAVE_SSE42_INLINE = have_x86_feat(t, .sse4_2),
        .HAVE_SSSE3_INLINE = have_x86_feat(t, .ssse3),
        .HAVE_XOP_INLINE = have_x86_feat(t, .xop),
        .HAVE_I686_INLINE = have_x86_feat(t, .cmov) and
            have_x86_feat(t, .cx8) and
            have_x86_feat(t, .vzeroupper) and
            have_x86_feat(t, .x87),
        .HAVE_MIPSFPU_INLINE = missing_mips_feat(t, .soft_float),
        .HAVE_MIPS32R2_INLINE = have_mips_feat(t, .mips32r2),
        .HAVE_MIPS32R5_INLINE = have_mips_feat(t, .mips32r5),
        .HAVE_MIPS64R2_INLINE = have_mips_feat(t, .mips64r2),
        .HAVE_MIPS32R6_INLINE = have_mips_feat(t, .mips32r6),
        .HAVE_MIPS64R6_INLINE = have_mips_feat(t, .mips64r6),
        .HAVE_MIPSDSP_INLINE = have_mips_feat(t, .dsp),
        .HAVE_MIPSDSPR2_INLINE = have_mips_feat(t, .dspr2),
        .HAVE_MSA_INLINE = have_mips_feat(t, .msa),
        .HAVE_LOONGSON2_INLINE = false,
        .HAVE_LOONGSON3_INLINE = false,
        .HAVE_MMI_INLINE = false,
        .HAVE_LSX_INLINE = false,
        .HAVE_LASX_INLINE = false,

        .HAVE_ALIGNED_STACK = true,
        .HAVE_FAST_64BIT = true,
        .HAVE_FAST_CLZ = true,
        .HAVE_FAST_CMOV = have_x86_feat(t, .cmov),
        .HAVE_FAST_FLOAT16 = have_x86_feat(t, .fast_imm16),
        .HAVE_SIMD_ALIGN_16 = true,
        .HAVE_SIMD_ALIGN_32 = true,
        .HAVE_SIMD_ALIGN_64 = true,
        .HAVE_MEMORYBARRIER = is_windows,
        .HAVE_MM_EMPTY = true,
        .HAVE_RDTSC = is_windows,
        .HAVE_SEM_TIMEDWAIT = !is_darwin and !is_windows,
        .HAVE_INLINE_ASM = true,
        .HAVE_SYMVER = true,
        .HAVE_X86ASM = t.cpu.arch.isX86(),
        .HAVE_BIGENDIAN = t.cpu.arch.endian() == .big,
        .HAVE_FAST_UNALIGNED = fastUnalignedLoads(t),
        .HAVE_ARPA_INET_H = !is_windows,
        .HAVE_ASM_HWPROBE_H = false,
        .HAVE_ASM_TYPES_H = !is_windows,
        .HAVE_CDIO_PARANOIA_H = false,
        .HAVE_CDIO_PARANOIA_PARANOIA_H = false,
