    @setEvalBranchQuota(2500);
    const config_asm = b.addConfigHeader(.{
        .style = .nasm,
        .include_path = "config.asm",
    }, common_config);

    const config_h = b.addConfigHeader(.{
        .style = .blank,
        .include_path = "config.h",
        .include_guard = "FFMPEG_CONFIG_H",
    }, .{
        .FFMPEG_CONFIGURATION = "",
        .FFMPEG_LICENSE = "LGPL version 2.1 or later",
        .CONFIG_THIS_YEAR = 2026,
        .FFMPEG_DATADIR = "/dev/null",
        .AVCONV_DATADIR = "/dev/null",
        .CC_IDENT = "clang 22.1.5 (CLANG)",
        .OS_NAME = osName(t.os.tag),
        .EXTERN_PREFIX = externPrefix(t),
    });
    if (externPrefix(t).len != 0) {
        config_h.addIdent("EXTERN_ASM", "_");
    } else {
        config_h.addValues(.{ .EXTERN_ASM = {} });
    }
    config_h.addValues(.{
        .BUILDSUF = "",
        .SLIBSUF = t.os.tag.dynamicLibSuffix(),
        .SWS_MAX_FILTER_SIZE = 256,
    });
    switch (t.cpu.arch) {
        .aarch64 => config_h.addIdent("AS_ARCH_LEVEL", asArchLevel(b, t)),
        else => {},
    }
    config_h.addValues(common_config);
    lib.root_module.addConfigHeader(config_h);

